export const WINDOWS_COLLECTOR_SCRIPT = "# Requires Windows PowerShell 5.1 or later. Read-only Windows 11 x64 snapshot.\n# MB and GB mean decimal bytes/1e6 and bytes/1e9. Process CPU readings use\n# paired samples, not cumulative process CPU time or proof of a cause.\n# Review the local JSON before sharing: even bounded process names can be private.\n[CmdletBinding()]\nparam(\n    [ValidatePattern('^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$')]\n    [string]$CollectionId = [guid]::NewGuid().ToString(),\n    [switch]$IncludeNetworkChecks\n)\n\nfunction ConvertTo-SampledCpuPercent {\n    param($BeforeSeconds, $AfterSeconds, $ElapsedSeconds, $LogicalProcessors)\n    if ($null -eq $BeforeSeconds -or $null -eq $AfterSeconds -or\n        $null -eq $ElapsedSeconds -or $null -eq $LogicalProcessors) { return $null }\n    $values = @([double]$BeforeSeconds, [double]$AfterSeconds, [double]$ElapsedSeconds, [double]$LogicalProcessors)\n    foreach ($value in $values) { if ([double]::IsNaN($value) -or [double]::IsInfinity($value)) { return $null } }\n    if ($BeforeSeconds -lt 0 -or $AfterSeconds -lt $BeforeSeconds -or $ElapsedSeconds -le 0 -or $LogicalProcessors -lt 1) { return $null }\n    $percent = [double](100 * ($AfterSeconds - $BeforeSeconds) / ($ElapsedSeconds * $LogicalProcessors))\n    return [math]::Round([math]::Min([double]100, $percent), 3)\n}\n\nfunction ConvertTo-SafeProcessName {\n    param([string]$Name)\n    $safe = ($Name -replace '[^a-zA-Z0-9 ._()-]', '_').Trim()\n    if (-not $safe) { $safe = 'unknown' }\n    return $safe.Substring(0, [math]::Min(128, $safe.Length))\n}\n\nfunction Add-CollectionError {\n    param($Errors, [string]$CheckId, [string]$Code)\n    if ($Errors.Count -ge 32) { return }\n    foreach ($entry in $Errors) { if ($entry.checkId -eq $CheckId -and $entry.code -eq $Code) { return } }\n    [void]$Errors.Add(@{ checkId = $CheckId; code = $Code })\n}\n\nfunction Read-ProcessCounters {\n    param($Errors)\n    $counters = @{}\n    try {\n        foreach ($item in @(Get-Process -ErrorAction Stop)) {\n            if ($item.Id -eq 0) { continue } # Idle time is not busy CPU.\n            $cpuSeconds = $null; $startTicks = $null; $memory = $null\n            try {\n                $startTicks = $item.StartTime.ToUniversalTime().Ticks\n                $cpuSeconds = $item.TotalProcessorTime.TotalSeconds\n            } catch { Add-CollectionError $Errors 'process-cpu' 'unavailable' }\n            try {\n                $workingSet = $item.WorkingSet64\n                if ($workingSet -ge 0) { $memory = [math]::Round($workingSet / 1000000.0, 3) }\n            } catch { Add-CollectionError $Errors 'process-memory' 'unavailable' }\n            $counters[[int]$item.Id] = @{\n                pid = [int]$item.Id; name = (ConvertTo-SafeProcessName $item.ProcessName)\n                startTicks = $startTicks; cpuSeconds = $cpuSeconds\n                sampledTicks = [Diagnostics.Stopwatch]::GetTimestamp(); memoryMb = $memory\n            }\n        }\n    } catch { Add-CollectionError $Errors 'process-list' 'unavailable' }\n    return $counters\n}\n\nfunction ConvertTo-MatchedProcessSample {\n    param($Before, $After, $LogicalProcessors)\n    $cpu = $null\n    if ($null -ne $Before -and $null -ne $Before.startTicks -and $null -ne $After.startTicks -and\n        $Before.pid -eq $After.pid -and $Before.startTicks -eq $After.startTicks) {\n        $elapsed = ($After.sampledTicks - $Before.sampledTicks) / [double][Diagnostics.Stopwatch]::Frequency\n        $cpu = ConvertTo-SampledCpuPercent $Before.cpuSeconds $After.cpuSeconds $elapsed $LogicalProcessors\n    }\n    return @{ pid = $After.pid; name = $After.name; cpuPercent = $cpu; memoryMb = $After.memoryMb }\n}\n\nfunction Invoke-WindowsSnapshot {\n    $ErrorActionPreference = 'Stop'\n    $errors = New-Object 'System.Collections.Generic.List[object]'\n    $snapshot = [ordered]@{\n        schemaVersion = 1; collectionId = $CollectionId.ToLowerInvariant(); platform = 'windows'\n        osVersion = 'unknown'; architecture = $null; source = 'collector'; collectorVersion = '1.0.0'\n        collectedAt = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ss.fffZ')\n        sampleIntervalMs = $null; cpuPercent = $null; memoryTotalMb = $null; memoryUsedMb = $null\n        diskTotalGb = $null; diskFreeGb = $null; dnsResolved = $null; gatewayLatencyMs = $null\n        processes = @(); eventExcerpts = @(); errors = @()\n    }\n    Add-CollectionError $errors 'event-excerpts-not-collected' 'unsupported'\n    # No default probes. Optional probing remains explicitly unavailable until a\n    # bounded implementation exists; requesting it never enables hidden traffic.\n    Add-CollectionError $errors 'dns-not-collected' 'unsupported'\n    Add-CollectionError $errors 'gateway-not-collected' 'unsupported'\n    if ($IncludeNetworkChecks) { Add-CollectionError $errors 'network-probes-not-implemented' 'unsupported' }\n    $supported = $false; $os = $null; $logical = $null\n    try {\n        $os = Get-CimInstance -ClassName Win32_OperatingSystem -OperationTimeoutSec 3 -ErrorAction Stop\n        $processors = @(Get-CimInstance -ClassName Win32_Processor -OperationTimeoutSec 3 -ErrorAction Stop)\n        if ($os.Version -match '^[0-9.]{1,100}$') { $snapshot.osVersion = [string]$os.Version }\n        $architectures = @($processors | Select-Object -ExpandProperty Architecture -Unique)\n        $supported = ([int]$os.BuildNumber -ge 22000 -and [int]$os.ProductType -eq 1 -and\n            $architectures.Count -eq 1 -and $architectures[0] -eq 9 -and $snapshot.osVersion -ne 'unknown')\n        if ($supported) { $snapshot.architecture = 'x64' }\n        $logical = ($processors | Measure-Object -Property NumberOfLogicalProcessors -Sum).Sum\n        if ($logical -lt 1) { $logical = $null }\n    } catch { Add-CollectionError $errors 'windows-version-or-architecture' 'unavailable' }\n    if (-not $supported) {\n        # Architecture/version are required canonical metadata. Unknown values\n        # cannot be represented honestly as a snapshot, so refuse without data.\n        throw 'Relay collector requires a verified Windows 11 x64 workstation.'\n    } else {\n        try {\n            if ($null -eq $os.TotalVisibleMemorySize -or $null -eq $os.FreePhysicalMemory) { throw 'Memory unavailable' }\n            $total = [double]$os.TotalVisibleMemorySize * 1024 / 1000000.0\n            $free = [double]$os.FreePhysicalMemory * 1024 / 1000000.0\n            if ($total -gt 0 -and $free -ge 0 -and $free -le $total) {\n                $snapshot.memoryTotalMb = [math]::Round($total, 3)\n                $snapshot.memoryUsedMb = [math]::Round($total - $free, 3)\n            } else { Add-CollectionError $errors 'memory' 'unavailable' }\n        } catch { Add-CollectionError $errors 'memory' 'unavailable' }\n        try {\n            $drive = @(Get-CimInstance -ClassName Win32_LogicalDisk -OperationTimeoutSec 3 -ErrorAction Stop |\n                Where-Object { $_.DeviceID -eq $os.SystemDrive -and $_.DriveType -eq 3 })\n            if ($drive.Count -eq 1 -and $null -ne $drive[0].Size -and $null -ne $drive[0].FreeSpace -and\n                $drive[0].Size -gt 0 -and $drive[0].FreeSpace -ge 0 -and $drive[0].FreeSpace -le $drive[0].Size) {\n                $snapshot.diskTotalGb = [math]::Round($drive[0].Size / 1000000000.0, 3)\n                $snapshot.diskFreeGb = [math]::Round($drive[0].FreeSpace / 1000000000.0, 3)\n            } else { Add-CollectionError $errors 'system-drive' 'unavailable' }\n        } catch { Add-CollectionError $errors 'system-drive' 'unavailable' }\n        $before = Read-ProcessCounters $errors\n        $watch = [Diagnostics.Stopwatch]::StartNew()\n        Start-Sleep -Milliseconds 1000\n        $after = Read-ProcessCounters $errors\n        $watch.Stop()\n        $snapshot.sampleIntervalMs = [math]::Round($watch.Elapsed.TotalMilliseconds, 3)\n        $samples = @($after.Values | ForEach-Object { ConvertTo-MatchedProcessSample $before[$_.pid] $_ $logical })\n        # Accessible process samples are not machine CPU: inaccessible, exited\n        # and short-lived processes are omitted. Do not infer a normal total.\n        Add-CollectionError $errors 'machine-cpu-not-collected' 'unavailable'\n        $snapshot.processes = @($samples | Sort-Object @{ Expression = 'cpuPercent'; Descending = $true },\n            @{ Expression = 'memoryMb'; Descending = $true }, @{ Expression = 'pid'; Descending = $false } | Select-Object -First 20)\n    }\n    $snapshot.errors = @($errors.ToArray())\n    return $snapshot\n}\n\n# Dot-sourcing exposes pure sampling functions to fixture tests without reading\n# the host. Direct -File invocation emits exactly one locally reviewable JSON.\nif ($MyInvocation.InvocationName -ne '.') {\n    $jsonOutput = Invoke-WindowsSnapshot | ConvertTo-Json -Depth 8 -Compress\n    [Console]::WriteLine($jsonOutput)\n\n    # Automatically copy to clipboard so user doesn't have to highlight text\n    try {\n        $jsonOutput | Set-Clipboard -ErrorAction SilentlyContinue\n        Write-Host \"`n[Relay] Telemetry copied to clipboard automatically!\" -ForegroundColor Green\n    } catch {}\n\n    # If a callback URL is provided, POST directly to the active browser session\n    if ($env:RELAY_CALLBACK_URL) {\n        try {\n            Invoke-RestMethod -Uri $env:RELAY_CALLBACK_URL -Method Post -Body $jsonOutput -ContentType \"application/json\" -ErrorAction SilentlyContinue\n            Write-Host \"[Relay] Telemetry uploaded directly to your active browser session!\" -ForegroundColor Green\n        } catch {}\n    }\n}\n\n";
export const UBUNTU_COLLECTOR_SCRIPT = "#!/usr/bin/env bash\n# Requires Ubuntu 22.04, 24.04, or compatible x64 workstation. Read-only Ubuntu snapshot.\n# MB and GB mean decimal bytes/1e6 and bytes/1e9. Process CPU readings use\n# paired samples, not cumulative process CPU time or proof of a cause.\n# Review the local JSON before sharing: even bounded process names can be private.\nset -euo pipefail\n\nCOLLECTION_ID=\"\"\nINCLUDE_NETWORK=false\n\nwhile [[ $# -gt 0 ]]; do\n  case \"$1\" in\n    --collection-id|-c)\n      COLLECTION_ID=\"$2\"\n      shift 2\n      ;;\n    --include-network)\n      INCLUDE_NETWORK=true\n      shift\n      ;;\n    *)\n      echo \"Unknown option: $1\" >&2\n      exit 1\n      ;;\n  esac\ndone\n\n# If no collection ID provided, generate a random UUID\nif [[ -z \"$COLLECTION_ID\" ]]; then\n  if [[ -f /proc/sys/kernel/random/uuid ]]; then\n    COLLECTION_ID=$(cat /proc/sys/kernel/random/uuid)\n  else\n    COLLECTION_ID=$(python3 -c \"import uuid; print(uuid.uuid4())\")\n  fi\nfi\n\n# Validate CollectionId UUID format\nUUID_REGEX='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'\nif [[ ! \"$COLLECTION_ID\" =~ $UUID_REGEX ]]; then\n  echo \"Invalid collection-id: must be a valid UUID.\" >&2\n  exit 1\nfi\n\n# Verify operating system and architecture\nif [[ ! -f /etc/os-release ]]; then\n  echo \"Relay collector requires a verified Ubuntu x64 workstation.\" >&2\n  exit 1\nfi\n\n# shellcheck source=/dev/null\nOS_ID=$(grep -E '^ID=' /etc/os-release | cut -d= -f2 | tr -d '\"')\nOS_VERSION=$(grep -E '^VERSION_ID=' /etc/os-release | cut -d= -f2 | tr -d '\"')\nARCH=$(uname -m)\n\nif [[ \"$OS_ID\" != \"ubuntu\" ]] || [[ \"$ARCH\" != \"x86_64\" ]]; then\n  echo \"Relay collector requires a verified Ubuntu x64 workstation.\" >&2\n  exit 1\nfi\n\n# Execute read-only sampling via embedded Python 3 script\nJSON_OUTPUT=$(python3 - \"$COLLECTION_ID\" \"$OS_VERSION\" \"$INCLUDE_NETWORK\" << 'PYEOF'\nimport sys\nimport os\nimport time\nimport glob\nimport re\nimport json\nfrom datetime import datetime, timezone\n\ncollection_id = sys.argv[1].lower()\nos_version = sys.argv[2]\ninclude_network = sys.argv[3] == \"true\"\n\nerrors = []\n\ndef add_error(check_id, code):\n    if len(errors) < 32:\n        for e in errors:\n            if e['checkId'] == check_id and e['code'] == code:\n                return\n        errors.append({'checkId': check_id, 'code': code})\n\n# 1. Uncollected fields\nadd_error('machine-cpu-not-collected', 'unavailable')\nadd_error('dns-not-collected', 'unsupported')\nadd_error('gateway-not-collected', 'unsupported')\nadd_error('event-excerpts-not-collected', 'unavailable')\n\nif include_network:\n    add_error('network-probes-not-implemented', 'unsupported')\n\n# 2. Memory collection from /proc/meminfo\nmemory_total_mb = None\nmemory_used_mb = None\ntry:\n    with open('/proc/meminfo', 'r') as f:\n        mem = {}\n        for line in f:\n            parts = line.split(':')\n            if len(parts) == 2:\n                mem[parts[0].strip()] = int(parts[1].strip().split()[0])\n    if 'MemTotal' in mem and 'MemAvailable' in mem:\n        total = (mem['MemTotal'] * 1024) / 1000000.0\n        free = (mem['MemAvailable'] * 1024) / 1000000.0\n        if total > 0 and free >= 0 and free <= total:\n            memory_total_mb = round(total, 3)\n            memory_used_mb = round(total - free, 3)\n        else:\n            add_error('memory', 'unavailable')\n    else:\n        add_error('memory', 'unavailable')\nexcept Exception:\n    add_error('memory', 'unavailable')\n\n# 3. Disk collection from / (root filesystem)\ndisk_total_gb = None\ndisk_free_gb = None\ntry:\n    st = os.statvfs('/')\n    total = (st.f_blocks * st.f_frsize) / 1000000000.0\n    free = (st.f_bavail * st.f_frsize) / 1000000000.0\n    if total > 0 and free >= 0 and free <= total:\n        disk_total_gb = round(total, 3)\n        disk_free_gb = round(free, 3)\n    else:\n        add_error('system-drive', 'unavailable')\nexcept Exception:\n    add_error('system-drive', 'unavailable')\n\n# 4. Paired process CPU sampling\ndef read_processes():\n    procs = {}\n    for path in glob.glob('/proc/[0-9]*/stat'):\n        try:\n            with open(path, 'r') as f:\n                content = f.read()\n            lparen = content.find('(')\n            rparen = content.rfind(')')\n            if lparen == -1 or rparen == -1 or rparen <= lparen:\n                continue\n            pid = int(content[:lparen].strip())\n            raw_name = content[lparen+1:rparen]\n            # Sanitize process name: alphanumeric, space, dot, underscore, hyphen, parens\n            safe_name = re.sub(r'[^a-zA-Z0-9 ._()-]', '_', raw_name).strip()\n            if not safe_name:\n                safe_name = 'unknown'\n            safe_name = safe_name[:128]\n            \n            rest = content[rparen+2:].split()\n            utime = int(rest[11])\n            stime = int(rest[12])\n            rss_pages = int(rest[21])\n            procs[pid] = {\n                'name': safe_name,\n                'ticks': utime + stime,\n                'rss_pages': rss_pages\n            }\n        except Exception:\n            continue\n    return procs\n\nlogical_processors = os.cpu_count() or 1\nticks_per_sec = os.sysconf('SC_CLK_TCK') if hasattr(os, 'sysconf') else 100\npage_size = os.sysconf('SC_PAGE_SIZE') if hasattr(os, 'sysconf') else 4096\n\nt_start = time.perf_counter()\nbefore_procs = read_processes()\ntime.sleep(1.0)\nt_end = time.perf_counter()\nafter_procs = read_processes()\n\nelapsed_seconds = t_end - t_start\nsample_interval_ms = round(elapsed_seconds * 1000.0, 3)\n\nprocess_samples = []\nfor pid, after in after_procs.items():\n    cpu_percent = None\n    if pid in before_procs:\n        before = before_procs[pid]\n        delta_ticks = after['ticks'] - before['ticks']\n        if delta_ticks >= 0 and elapsed_seconds > 0 and logical_processors >= 1:\n            raw_percent = (100.0 * delta_ticks) / (elapsed_seconds * ticks_per_sec * logical_processors)\n            cpu_percent = round(min(100.0, max(0.0, raw_percent)), 3)\n    \n    memory_mb = round((after['rss_pages'] * page_size) / 1000000.0, 3)\n    process_samples.append({\n        'pid': pid,\n        'name': after['name'],\n        'cpuPercent': cpu_percent,\n        'memoryMb': memory_mb\n    })\n\n# Sort top 20 processes by cpuPercent DESC (None last), memoryMb DESC, pid ASC\nprocess_samples.sort(\n    key=lambda p: (\n        p['cpuPercent'] if p['cpuPercent'] is not None else -1.0,\n        p['memoryMb'] if p['memoryMb'] is not None else -1.0,\n        -p['pid']\n    ),\n    reverse=True\n)\ntop_processes = process_samples[:20]\n\nsnapshot = {\n    'schemaVersion': 1,\n    'collectionId': collection_id,\n    'platform': 'ubuntu',\n    'osVersion': os_version,\n    'architecture': 'x64',\n    'source': 'collector',\n    'collectorVersion': '1.0.0',\n    'collectedAt': datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'),\n    'sampleIntervalMs': sample_interval_ms,\n    'cpuPercent': None,\n    'memoryTotalMb': memory_total_mb,\n    'memoryUsedMb': memory_used_mb,\n    'diskTotalGb': disk_total_gb,\n    'diskFreeGb': disk_free_gb,\n    'dnsResolved': None,\n    'gatewayLatencyMs': None,\n    'processes': top_processes,\n    'eventExcerpts': [],\n    'errors': errors\n}\n\nprint(json.dumps(snapshot, separators=(',', ':')))\nPYEOF\n)\n\nprintf '%s\\n' \"$JSON_OUTPUT\"\n\n# Copy to clipboard automatically if pbcopy / xclip / wl-copy is available\nif command -v pbcopy >/dev/null 2>&1; then\n  printf '%s' \"$JSON_OUTPUT\" | pbcopy\n  echo \"[Relay] Telemetry automatically copied to your clipboard!\" >&2\nelif command -v wl-copy >/dev/null 2>&1; then\n  printf '%s' \"$JSON_OUTPUT\" | wl-copy\n  echo \"[Relay] Telemetry automatically copied to your clipboard!\" >&2\nelif command -v xclip >/dev/null 2>&1; then\n  printf '%s' \"$JSON_OUTPUT\" | xclip -selection clipboard\n  echo \"[Relay] Telemetry automatically copied to your clipboard!\" >&2\nfi\n\n";
export const MACOS_COLLECTOR_SCRIPT = "#!/usr/bin/env bash\n# Requires macOS 15+ on Apple Silicon (arm64). Read-only macOS snapshot.\n# MB and GB mean decimal bytes/1e6 and bytes/1e9. Process CPU readings use\n# paired samples, not cumulative process CPU time or proof of a cause.\n# Review the local JSON before sharing: even bounded process names can be private.\nset -euo pipefail\n\nCOLLECTION_ID=\"\"\nINCLUDE_NETWORK=false\n\nwhile [[ $# -gt 0 ]]; do\n  case \"$1\" in\n    --collection-id|-c)\n      COLLECTION_ID=\"$2\"\n      shift 2\n      ;;\n    --include-network)\n      INCLUDE_NETWORK=true\n      shift\n      ;;\n    *)\n      echo \"Unknown option: $1\" >&2\n      exit 1\n      ;;\n  esac\ndone\n\n# If no collection ID provided, generate a random UUID\nif [[ -z \"$COLLECTION_ID\" ]]; then\n  if command -v uuidgen >/dev/null 2>&1; then\n    COLLECTION_ID=$(uuidgen | tr '[:upper:]' '[:lower:]')\n  else\n    COLLECTION_ID=$(python3 -c \"import uuid; print(uuid.uuid4())\")\n  fi\nfi\n\n# Validate CollectionId UUID format\nUUID_REGEX='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'\nif [[ ! \"$COLLECTION_ID\" =~ $UUID_REGEX ]]; then\n  echo \"Invalid collection-id: must be a valid UUID.\" >&2\n  exit 1\nfi\n\n# Verify operating system and architecture\nOS_NAME=$(uname -s 2>/dev/null || echo \"unknown\")\nARCH=$(uname -m 2>/dev/null || echo \"unknown\")\n\nif [[ \"$OS_NAME\" != \"Darwin\" ]] || [[ \"$ARCH\" != \"arm64\" ]]; then\n  echo \"Relay collector requires a verified macOS on Apple Silicon (arm64) workstation.\" >&2\n  exit 1\nfi\n\nOS_VERSION=$(sw_vers -productVersion 2>/dev/null || echo \"15.0\")\n\n# Execute read-only sampling via embedded Python 3 script\nJSON_OUTPUT=$(python3 - \"$COLLECTION_ID\" \"$OS_VERSION\" \"$INCLUDE_NETWORK\" << 'PYEOF'\nimport sys\nimport os\nimport time\nimport subprocess\nimport re\nimport json\nfrom datetime import datetime, timezone\n\ncollection_id = sys.argv[1].lower()\nos_version = sys.argv[2]\ninclude_network = sys.argv[3] == \"true\"\n\nerrors = []\n\ndef add_error(check_id, code):\n    if len(errors) < 32:\n        for e in errors:\n            if e['checkId'] == check_id and e['code'] == code:\n                return\n        errors.append({'checkId': check_id, 'code': code})\n\n# 1. Uncollected fields\nadd_error('machine-cpu-not-collected', 'unavailable')\nadd_error('dns-not-collected', 'unsupported')\nadd_error('gateway-not-collected', 'unsupported')\nadd_error('event-excerpts-not-collected', 'unavailable')\n\nif include_network:\n    add_error('network-probes-not-implemented', 'unsupported')\n\n# 2. Memory collection via sysctl and vm_stat\nmemory_total_mb = None\nmemory_used_mb = None\ntry:\n    total_bytes = int(subprocess.check_output(['sysctl', '-n', 'hw.memsize'], timeout=3).strip())\n    vm_out = subprocess.check_output(['vm_stat'], timeout=3).decode('utf8', errors='ignore')\n    \n    # vm_stat page size\n    page_size = 16384\n    m_page = re.search(r'page size of (\\d+) bytes', vm_out)\n    if m_page:\n        page_size = int(m_page.group(1))\n    \n    pages_free = 0\n    pages_spec = 0\n    for line in vm_out.splitlines():\n        if 'Pages free:' in line:\n            pages_free = int(re.sub(r'[^0-9]', '', line.split(':')[1]))\n        elif 'Pages speculative:' in line:\n            pages_spec = int(re.sub(r'[^0-9]', '', line.split(':')[1]))\n            \n    free_bytes = (pages_free + pages_spec) * page_size\n    total_mb = total_bytes / 1000000.0\n    free_mb = free_bytes / 1000000.0\n    \n    if total_mb > 0 and free_mb >= 0 and free_mb <= total_mb:\n        memory_total_mb = round(total_mb, 3)\n        memory_used_mb = round(total_mb - free_mb, 3)\n    else:\n        add_error('memory', 'unavailable')\nexcept Exception:\n    add_error('memory', 'unavailable')\n\n# 3. Disk collection via statvfs on /\ndisk_total_gb = None\ndisk_free_gb = None\ntry:\n    st = os.statvfs('/')\n    total = (st.f_blocks * st.f_frsize) / 1000000000.0\n    free = (st.f_bavail * st.f_frsize) / 1000000000.0\n    if total > 0 and free >= 0 and free <= total:\n        disk_total_gb = round(total, 3)\n        disk_free_gb = round(free, 3)\n    else:\n        add_error('system-drive', 'unavailable')\nexcept Exception:\n    add_error('system-drive', 'unavailable')\n\n# 4. Paired process CPU sampling using ps\ndef parse_cputime_to_seconds(t_str):\n    # Formats: mm:ss.ss or hh:mm:ss or dd-hh:mm:ss\n    try:\n        days = 0\n        if '-' in t_str:\n            parts_d = t_str.split('-')\n            days = int(parts_d[0])\n            t_str = parts_d[1]\n        parts = t_str.split(':')\n        if len(parts) == 2:\n            return days * 86400.0 + int(parts[0]) * 60.0 + float(parts[1])\n        elif len(parts) == 3:\n            return days * 86400.0 + int(parts[0]) * 3600.0 + int(parts[1]) * 60.0 + float(parts[2])\n    except Exception:\n        pass\n    return None\n\ndef read_processes():\n    procs = {}\n    try:\n        out = subprocess.check_output(\n            ['ps', '-A', '-o', 'pid=,cputime=,rss=,comm='],\n            timeout=5\n        ).decode('utf8', errors='ignore')\n        \n        for line in out.splitlines():\n            line = line.strip()\n            if not line:\n                continue\n            parts = line.split(None, 3)\n            if len(parts) < 4:\n                continue\n            pid_str, cputime_str, rss_str, comm_raw = parts\n            pid = int(pid_str)\n            sec = parse_cputime_to_seconds(cputime_str)\n            rss_kb = int(rss_str)\n            \n            # Sanitize process name: basename only, clean characters\n            base_comm = os.path.basename(comm_raw)\n            safe_name = re.sub(r'[^a-zA-Z0-9 ._()-]', '_', base_comm).strip()\n            if not safe_name:\n                safe_name = 'unknown'\n            safe_name = safe_name[:128]\n            \n            procs[pid] = {\n                'name': safe_name,\n                'cpuSeconds': sec,\n                'memoryMb': round((rss_kb * 1024) / 1000000.0, 3)\n            }\n    except Exception:\n        pass\n    return procs\n\nlogical_processors = os.cpu_count() or 1\n\nt_start = time.perf_counter()\nbefore_procs = read_processes()\ntime.sleep(1.0)\nt_end = time.perf_counter()\nafter_procs = read_processes()\n\nelapsed_seconds = t_end - t_start\nsample_interval_ms = round(elapsed_seconds * 1000.0, 3)\n\nprocess_samples = []\nfor pid, after in after_procs.items():\n    cpu_percent = None\n    if pid in before_procs and after['cpuSeconds'] is not None and before_procs[pid]['cpuSeconds'] is not None:\n        delta_sec = after['cpuSeconds'] - before_procs[pid]['cpuSeconds']\n        if delta_sec >= 0 and elapsed_seconds > 0 and logical_processors >= 1:\n            raw_percent = (100.0 * delta_sec) / (elapsed_seconds * logical_processors)\n            cpu_percent = round(min(100.0, max(0.0, raw_percent)), 3)\n            \n    process_samples.append({\n        'pid': pid,\n        'name': after['name'],\n        'cpuPercent': cpu_percent,\n        'memoryMb': after['memoryMb']\n    })\n\n# Sort top 20 processes by cpuPercent DESC, memoryMb DESC, pid ASC\nprocess_samples.sort(\n    key=lambda p: (\n        p['cpuPercent'] if p['cpuPercent'] is not None else -1.0,\n        p['memoryMb'] if p['memoryMb'] is not None else -1.0,\n        -p['pid']\n    ),\n    reverse=True\n)\ntop_processes = process_samples[:20]\n\nsnapshot = {\n    'schemaVersion': 1,\n    'collectionId': collection_id,\n    'platform': 'macos',\n    'osVersion': os_version,\n    'architecture': 'arm64',\n    'source': 'collector',\n    'collectorVersion': '1.0.0',\n    'collectedAt': datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'),\n    'sampleIntervalMs': sample_interval_ms,\n    'cpuPercent': None,\n    'memoryTotalMb': memory_total_mb,\n    'memoryUsedMb': memory_used_mb,\n    'diskTotalGb': disk_total_gb,\n    'diskFreeGb': disk_free_gb,\n    'dnsResolved': None,\n    'gatewayLatencyMs': None,\n    'processes': top_processes,\n    'eventExcerpts': [],\n    'errors': errors\n}\n\nprint(json.dumps(snapshot, separators=(',', ':')))\nPYEOF\n)\n\nprintf '%s\\n' \"$JSON_OUTPUT\"\n\n# Copy to clipboard automatically if pbcopy is available\nif command -v pbcopy >/dev/null 2>&1; then\n  printf '%s' \"$JSON_OUTPUT\" | pbcopy\n  echo \"[Relay] Telemetry automatically copied to your clipboard!\" >&2\nfi\n\n";

export interface CollectorScriptInfo {
  content: string;
  filename: string;
  contentType: string;
  platform: "windows" | "ubuntu" | "macos";
}

export function getCollectorScript(platform: string): CollectorScriptInfo | null {
  const norm = platform.toLowerCase().replace(/\.(ps1|sh)$/, "");
  if (norm === "windows" || norm === "windows11" || norm === "win") {
    return {
      content: WINDOWS_COLLECTOR_SCRIPT,
      filename: "relay-windows11-collector.ps1",
      contentType: "text/plain; charset=utf-8",
      platform: "windows",
    };
  }
  if (norm === "ubuntu" || norm === "linux" || norm === "ubuntu_2204" || norm === "ubuntu_2404") {
    return {
      content: UBUNTU_COLLECTOR_SCRIPT,
      filename: "relay-ubuntu-collector.sh",
      contentType: "text/x-shellscript; charset=utf-8",
      platform: "ubuntu",
    };
  }
  if (norm === "macos" || norm === "darwin" || norm === "mac" || norm === "macos_apple_silicon") {
    return {
      content: MACOS_COLLECTOR_SCRIPT,
      filename: "relay-macos-collector.sh",
      contentType: "text/x-shellscript; charset=utf-8",
      platform: "macos",
    };
  }
  return null;
}

/**
 * Returns safe non-elevated command snippets executing from system temporary folders (Fix 3).
 */
export function getCollectorTerminalSnippet(platform: string, origin: string): string {
  const norm = platform.toLowerCase().replace(/\.(ps1|sh)$/, "");
  if (norm === "windows" || norm === "windows11" || norm === "win") {
    return [
      "[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12",
      "$scriptPath = Join-Path $env:TEMP \"relay-inspect.ps1\"",
      "irm " + origin + "/api/collectors/windows11.ps1 -OutFile $scriptPath",
      "Unblock-File -Path $scriptPath -ErrorAction SilentlyContinue",
      "powershell -NoProfile -ExecutionPolicy Bypass -File $scriptPath",
    ].join("\n");
  }
  if (norm === "macos" || norm === "darwin" || norm === "mac" || norm === "macos_apple_silicon") {
    return [
      "# 1. Download non-elevated collector to /tmp:",
      "curl -sSL " + origin + "/api/collectors/macos.sh -o /tmp/relay-inspect.sh",
      "",
      "# 2. Review and run:",
      "less /tmp/relay-inspect.sh",
      "zsh /tmp/relay-inspect.sh",
    ].join("\n");
  }
  return [
    "# 1. Download non-elevated collector to /tmp:",
    "curl -sSL " + origin + "/api/collectors/ubuntu.sh -o /tmp/relay-inspect.sh",
    "",
    "# 2. Review and run:",
    "less /tmp/relay-inspect.sh",
    "bash /tmp/relay-inspect.sh",
  ].join("\n");
}
